      }
      if (tag === 'engine') {
        fail('an engine node inside the tree; nothing of the engine draws ' +
          'inside a Client')
      }
      if (tag === 'Markdown' && node.press !== undefined) {
        fail('a Markdown with onLinkPress inside the tree; a surface ' +
          'module answers its own pointer with surface.onPointer')
      }
      const out = { type: tag }
      if (node.props !== undefined) out.props = propsOf(node.props)
      if (node.hover !== undefined) out.hover = propsOf(node.hover)
      const closureKey = PRESSABLE[tag]
      if (closureKey !== undefined) {
        const closure = node[closureKey]
        if (typeof closure !== 'function') {
          fail('a ' + tag + ' without its handler (build it with ' +
            'surface.elements.' + tag + ')')
        }
        const handle = ++instance.heldCounter
        instance.held.set(handle, closure)
        out.held = handle
        return out
      }
      const children = node.children
      if (children !== undefined) {
        if (!_isArray(children)) fail('children that are not an array')
        const copied = []
        for (let i = 0; i < children.length; i++) {
          copied.push(walk(children[i], depth + 1))
        }
        out.children = copied
      }
      return out
    }
    const text = _stringify(walk(tree, 0))
    if (text.length > limits.chars) {
      fail('a tree serializing to more than ' + limits.chars + ' characters')
    }
    return text
  }

  // What a rejection says, read here and handed to the host as text.
  const reasonText = error => {
    try {
      const isError = typeof error === 'object' && error !== null
      const message = isError ? error.message : error
      return typeof message === 'string' ? message : _String(message)
    } catch {
      return 'a rejection that could not be read'
    }
  }

  // Tells the host a fault. A desktop frame is served this script as it is,
  // and one shipped before \`fault\` hands over a host without it: there the
  // reason is thrown on whole, as it came out when nobody heard.
  const faulted = (id, error) => {
    if (typeof host.fault !== 'function') throw error
    host.fault(id, reasonText(error))
  }

  // What a user function returned, heard when it is a promise: an async
  // handler that throws rejects one, and a rejection nobody hears is the
  // process's to end a session over. Heard, it is the instance's fault.
  const heard = (id, out) => {
    const isHeld =
      (typeof out === 'object' && out !== null) || typeof out === 'function'
    if (!isHeld) return out
    try {
      _then.call(_resolve(out), undefined, error => faulted(id, error))
    } catch (error) {
      faulted(id, error)
    }
    return out
  }

  // Every user function is called bare (no receiver): its \`this\` is
  // undefined, never the instance record. Only render answers anything: the
  // tree's JSON text; a listener's return value stays here, heard.
  function act(id, instance, kind, payload) {
    switch (kind) {
      case 'render': {
        instance.scheduled = false
        const render = instance.fn
        return exportTree(
          instance,
          heard(id, render(instance.props, instance.surface)),
        )
      }
      case 'pointer': {
        const listener = instance.pointer
        if (listener !== null) heard(id, listener(payload))
        return undefined
      }
      case 'key': {
        const listener = instance.key
        if (listener !== null) heard(id, listener(payload))
        return undefined
      }
      case 'tick': {
        const fn = instance.timers.get(payload)
        if (fn !== undefined) heard(id, fn())
        return undefined
      }
      case 'held': {
        const fn = instance.held.get(payload.handle)
        if (fn !== undefined) heard(id, fn(payload.event))
        return undefined
      }
      default:
        return fail('unknown surface call ' + kind)
    }
  }

  return freeze({
    __proto__: null,
    mount: (id, fn, props) => {
      if (typeof fn !== 'function') {
        fail('the surface module export is not a function', _TypeError)
      }
      const instance = {
        fn, props, state: undefined, columns: 0, rows: 0, scheduled: false,
        pointer: null, key: null, timers: new _Map(), surface: null,
        held: new _Map(), heldCounter: 0,
      }
      instance.surface = surfaceOf(id, instance)
      instances.set(id, instance)
    },
    setProps: (id, props) => { instanceOf(id).props = props },
    resize: (id, columns, rows) => {
      const instance = instanceOf(id)
      instance.columns = columns
      instance.rows = rows
    },
    stage: (id, kind, payload) => {
      const instance = instanceOf(id)
      pending = () => act(id, instance, kind, payload)
    },
    // The closures exportTree held for elements a redraw retired.
    dropHeld: (id, handles) => {
      const instance = instances.get(id)
      if (instance === undefined) return
      for (let i = 0; i < handles.length; i++) instance.held.delete(handles[i])
    },
    hasListener: (id, kind) => {
      const instance = instances.get(id)
      if (instance === undefined) return false
      const listener = kind === 'pointer' ? instance.pointer : instance.key
      return listener !== null
    },
    unmount: id => {
      const instance = instances.get(id)
      if (instance === undefined) return
      instances.delete(id)
      instance.timers.clear()
      instance.held.clear()
      instance.pointer = null
      instance.key = null
    },
  })
})

// atom-brand/atom-brand.js
const ATOM_BRAND = Symbol.for('claude-code.state.atom');

// atom-value-of/atom-value-of.js
function atomValueOf(atom, stored) {
    if (atom.shape === undefined) {
        return stored === undefined ? atom.initial : stored;
    }
    const kept = stored;
    const isSameShape = kept?.shape === atom.shape && kept.value !== undefined;
    return isSameShape ? kept.value : atom.initial;
}

// atom/atom.js
export const atom = (ref, initial, options) => Object.freeze({
    [ATOM_BRAND]: true,
    ref: frozenRef(ref),
    initial: deepFrozen(initial),
    ...(options?.shape !== undefined && { shape: options.shape }),
});

// deep-frozen/deep-frozen.js
function deepFrozen(value) {
    if (typeof value !== 'object' || value === null || Object.isFrozen(value)) {
        return value;
    }
    for (const member of Object.values(value)) {
        deepFrozen(member);
    }
    return Object.freeze(value);
}

// derive/derive.js
export const derive = (sources, compute) => {
    const memo = {};
    return Object.freeze({
        [DERIVED_BRAND]: memo,
        sources: Object.freeze(sources.map(one => {
            const isMade = isAtom(one) || isDerived(one);
            return isMade ? one : frozenRef(one);
        })),
        compute,
    });
};

// derived-brand/derived-brand.js
const DERIVED_BRAND = Symbol.for('claude-code.state.derived');

// frozen-ref/frozen-ref.js
function frozenRef(ref, id = ref.id) {
    const { plugin, key } = ref;
    return Object.freeze(id === undefined ? { plugin, key } : { plugin, key, id });
}

// has-brand/has-brand.js
const hasBrand = (source, brand) => typeof source === 'object' &&
    source !== null &&
    source[brand] !== undefined;

// is-atom/is-atom.js
const isAtom = (source) => hasBrand(source, ATOM_BRAND);

// is-derived/is-derived.js
const isDerived = (source) => hasBrand(source, DERIVED_BRAND);

// member-of/member-of.js
export const memberOf = (family, e) => (isAtom(family)
    ? Object.freeze({
        ...family,
        [ATOM_BRAND]: true,
        ref: frozenRef(family.ref, e.requestId),
    })
    : frozenRef(family, e.requestId));

// peek/peek.js
async function peek(state, source) {
    if (isAtom(source)) {
        const held = await state.get(source.ref);
        return {
            value: atomValueOf(source, held.value),
            versions: [held.version],
        };
    }
    if (!isDerived(source)) {
        const held = await state.get(source);
        return { value: held.value, versions: [held.version] };
    }
    const parts = await Promise.all(source.sources.map(one => peek(state, one)));
    const versions = parts.flatMap(part => part.versions);
    const key = versions.join(',');
    const memo = source[DERIVED_BRAND];
    if (memo?.versions !== key && memo !== undefined) {
        memo.value = source.compute(...parts.map(part => part.value));
        memo.versions = key;
    }
    return { value: memo?.value, versions };
}

// read/read.js
export const read = async ($, source) => (await peek($.state, source)).value;

// stored-value-of/stored-value-of.js
const storedValueOf = (atom, value) => atom.shape === undefined ? value : { shape: atom.shape, value };

// update-tries-max/update-tries-max.js
const UPDATE_TRIES_MAX = 64;

// update/update.js
export const update = async ($, target, change) => {
    const state = $.state;
    const ref = isAtom(target) ? target.ref : target;
    for (let tries = 0; tries < UPDATE_TRIES_MAX; tries += 1) {
        const held = await state.get(ref);
        const current = isAtom(target)
            ? atomValueOf(target, held.value)
            : held.value;
        const next = change(current);
        const stored = isAtom(target) ? storedValueOf(target, next) : next;
        const wrote = await state.set(ref, stored, { ifVersion: held.version });
        if (wrote.isSet) {
            return next;
        }
    }
    throw new Error('update: the value was written by another every time it was read, up ' +
        'to the bound on tries; nothing was written');
};
